17	import { useMemberStore } from "@/hooks/useMemberStore";
18	import { useTreeStore, isVirtualId } from "@/hooks/useTreeStore";
19	import { useFamilyTreeSettings } from "@/hooks/useFamilyTreeSettings";
20	import { FlowPanelControls } from "@/components/view/tree-view/FlowPanelControls";
21	import GenerationLines from "@/components/view/tree-view/GenerationLines";
22	import { CanvasSearch } from "@/components/view/tree-view/CanvasSearch";
23	import { EmptyTreeState } from "@/components/view/tree-view/EmptyTreeState";
24	import { MemberControls } from "@/components/view/tree-view/MemberControls";
25	import { ConnectionRelationCard } from "@/components/view/tree-view/ConnectionRelationCard";
26	import { MemberSheet } from "@/components/shared/member-sheet/MemberSheet";
27	import { FamilyNode } from "@/components/view/tree-view/node/FamilyNode";
28	import {
29	  UnionNode,
30	  UNION_NODE_SIZE,
31	} from "@/components/view/tree-view/node/UnionNode";
32	import { AddRelationDialog } from "@/components/view/tree-view/dialog/AddRelationDialog";
33	import { RelationEdge } from "@/components/view/tree-view/edge/RelationEdge";
34	import { useFlowNodes } from "@/hooks/useFlowNodes";
35	import { useFlowEdges } from "@/hooks/useFlowEdges";
36	import { useFlowInteractions } from "@/hooks/useFlowInteractions";
37	import { useUndoRedo } from "@/hooks/useUndoRedo";
38	import { useDerivedFlowView } from "@/hooks/useDerivedFlowView";
39	import { useIsMobile } from "@/hooks/useMobile";
40	import { memberPairKey } from "@/utils/graphUtils";
41	import {
42	  resolveRelationStyle,
43	  relationStyleOverrideFromType,
44	} from "@/utils/relationStyleUtils";
45	import { fitViewToAllNodes } from "@/utils/flowFit";
46	import { useMemberLocator } from "@/hooks/useMemberLocator";
47	import { useConnectionMode } from "@/hooks/useConnectionMode";
48	import { useSelectionMode } from "@/hooks/useSelectionMode";
49	import { SelectionModeController } from "@/components/view/tree-view/SelectionModeController";
50	import { useRelationCreation } from "@/hooks/useRelationCreation";
51	import { usePendingMember } from "@/hooks/usePendingMember";
52	import { useTranslation } from "react-i18next";
53	import { toast } from "sonner";
54	import { useFeature } from "@/hooks/useAuthStore";
55	import { useTaskStore } from "@/hooks/useTaskStore";
56	import { useDeferredStoreLoad } from "@/hooks/useDeferredStoreLoad";
57	import { useMemberSheetStore } from "@/hooks/useMemberSheetStore";
58	import { NoDatabasePlaceholder } from "@/components/layout/NoDatabasePlaceholder";
59	import { PresenceChips } from "@/components/layout/PresenceChips";
60	import {
61	  clearMemberSheetDeepLink,
62	  readMemberSheetDeepLink,
63	} from "@/utils/memberSheetState";
64	import { getGenerationLineGap } from "@/utils/generationLineSpacing";
65	
66	const nodeTypes = { familyMember: FamilyNode, unionNode: UnionNode };
67	const edgeTypes = { relation: RelationEdge };
68	
69	interface FlowPanelProps {
70	  // Chromeless, purely-visual rendering for the public read-only tree view:
71	  // no member sheet, no edit dialogs, no node action buttons.
72	  publicView?: boolean;
73	}
74	
75	// Stable reference for "no connection-path highlight". findConnectionPathHighlight
76	// returns a fresh (often empty) Set on every members change; passing that straight
77	// into useFlowEdges would re-derive viewEdges from a still-stale baseEdges during the
78	// async worker round-trip, briefly re-adding a just-deleted edge (a one-frame flicker).
79	// An empty highlight set has no visual effect, so we collapse it to one shared instance.
80	const EMPTY_EDGE_KEYS: ReadonlySet<string> = new Set<string>();
81	
82	export const FlowPanel = ({ publicView = false }: FlowPanelProps = {}) => {
83	  const { t } = useTranslation();
84	  const treeLinksEnabled = useFeature("tree_links");
85	  const taskRestrictions = useTreeStore((s) => s.selectedTree?.restrictions);
86	  const tasksEnabled =
87	    useFeature("research_tasks") && !taskRestrictions?.includes("tasks");
88	  const { refreshTasks, initialized: tasksInitialized } = useTaskStore();
89	  // Open-task node indicators need the task list; skip on public trees where
90	  // the task endpoints require authentication.
91	  useDeferredStoreLoad(
92	    tasksInitialized || !tasksEnabled || publicView,
93	    refreshTasks,
94	  );
95	  const activeTree = useTreeStore((s) => s.selectedTree);
96	  const openTreeAndLocateMember = useTreeStore(
97	    (s) => s.openTreeAndLocateMember,
98	  );
99	  const savedMemberSheetState = useMemberSheetStore((s) =>
100	    activeTree?.id ? s.openSheets[activeTree.id] : undefined,
101	  );
102	  const setOpenSheet = useMemberSheetStore((s) => s.setOpenSheet);
103	  const clearOpenSheet = useMemberSheetStore((s) => s.clearOpenSheet);
104	  const availableTreeCount = useTreeStore(
105	    (s) => s.trees.length + s.virtualViews.length,
106	  );
107	  const isMobile = useIsMobile();
108	  const {
109	    members,
110	    removeMember,
111	    updateLayout,
112	    windowed,
113	    focusRootId,
114	    neighborhoodTruncated,
115	    totalMemberCount,
116	    setFocusRoot,
117	    pendingLocateMemberId,
118	    setPendingLocateMemberId,
119	  } = useMemberStore();
120	  const canWrite = activeTree?.role !== "viewer";
121	  const isVirtualView = !!activeTree?.id && isVirtualId(activeTree.id);
122	  const isCanvasReadOnly = isMobile || !canWrite;
123	  // Virtual views allow dragging even though canWrite is false (role: "viewer").
124	  // Positions are persisted independently in VirtualViewPosition.
125	  const canDragLayout = !isMobile && (canWrite || isVirtualView);
126	  useUndoRedo(!isCanvasReadOnly);
127	  const { isReady } = useTreeStore();
128	
129	  const {
130	    edgeType,
131	    isLockedScreen,
132	    visibleRelationTypes,
133	    viewports,
134	    setViewport,
135	    generationLineGaps,
136	  } = useFamilyTreeSettings();
137	  const DEFAULT_VIEWPORT = { x: 0, y: 0, zoom: 1 };
138	  const viewport = (activeTree && viewports[activeTree.id]) ?? DEFAULT_VIEWPORT;
139	  const generationLineGap = getGenerationLineGap(
140	    activeTree ? generationLineGaps[activeTree.id] : undefined,
141	  );
142	  const [rfInstance, setRfInstance] = useState<ReactFlowInstance | null>(null);
143	  const [nodes, setNodes] = useState<Node[]>([]);
144	  const [edges, setEdges] = useState<Edge[]>([]);
145	  const [membersToDelete, setMembersToDelete] = useState<Member[]>([]);
146	  const [selectedNodes, setSelectedNodes] = useState<Node[]>([]);
147	
148	  // --- Extracted hooks ---
149	  const locator = useMemberLocator(members, rfInstance);
150	
151	  // Center the counterpart after navigating into a linked tree: consume the
152	  // one-shot locate request once the member shows up in the loaded set. In
153	  // windowed mode the counterpart may lie outside the current neighborhood —
154	  // re-focus the window on it once and locate after the reload.
155	  const attemptedLinkedFocusRef = useRef<string | null>(null);
156	  const consumedLocateRef = useRef<string | null>(null);
157	  useEffect(() => {
158	    if (!pendingLocateMemberId) {
159	      consumedLocateRef.current = null;
160	      return;
161	    }
162	    const target = members.find((m) => m.id === pendingLocateMemberId);
163	    if (target) {
164	      // Wait until the canvas is fully up before consuming the request: on a
165	      // fresh mount (e.g. arriving from the map view) rfInstance is null,
166	      // the nodes land a couple of commits later, and React Flow applies its
167	      // initial viewport only once it is measured — centering before that
168	      // gets silently overridden. viewportInitialized flips after that
169	      // initial viewport is in; the `nodes` dep re-runs this until then.
170	      if (!rfInstance?.viewportInitialized || !rfInstance.getNode(target.id))
171	        return;
172	      // Commits queued behind the mount burst still carry the pre-consumption
173	      // store snapshot — don't re-center for each of them.
174	      if (consumedLocateRef.current === pendingLocateMemberId) return;
175	      consumedLocateRef.current = pendingLocateMemberId;
176	      attemptedLinkedFocusRef.current = null;
177	      setPendingLocateMemberId(null);
178	      locator.locateMember(target);
179	      return;
180	    }
181	    if (members.length === 0) return; // still loading
182	    if (windowed && attemptedLinkedFocusRef.current !== pendingLocateMemberId) {
183	      attemptedLinkedFocusRef.current = pendingLocateMemberId;
184	      void setFocusRoot(pendingLocateMemberId);
185	      return;
186	    }
187	    // Fully loaded (or window already re-focused) and still absent: the
188	    // counterpart no longer exists — drop the request.
189	    attemptedLinkedFocusRef.current = null;
190	    setPendingLocateMemberId(null);
191	  }, [
192	    pendingLocateMemberId,
193	    members,
194	    windowed,
195	    setFocusRoot,
196	    setPendingLocateMemberId,
197	    locator,
198	    rfInstance,
199	    nodes,
200	  ]);
201	
202	  // Mutual exclusion between connection mode and selection mode: entering one
203	  // exits the other. `connection` is instantiated first, so its
204	  // onEnterConnectionMode callback can't close over `selection` directly
205	  // (TDZ / stale closure). Instead it reads the latest selection-mode state
206	  // and toggle function through a ref that is kept up to date every render.
207	  const exitSelectionRef = useRef<{
208	    isSelectionMode: boolean;
209	    toggleSelectionMode: () => void;
210	  } | null>(null);
211	
212	  const connection = useConnectionMode(members, () => {
213	    setSelectedNodes([]);
214	    if (exitSelectionRef.current?.isSelectionMode) {
215	      exitSelectionRef.current.toggleSelectionMode();
216	    }
217	  });
218	
219	  const selection = useSelectionMode(() => {
220	    if (connection.isConnectionMode) connection.toggleConnectionMode();
221	  });
222	
223	  useEffect(() => {
224	    exitSelectionRef.current = selection;
225	  });
226	
227	  // Clear the marquee selection when selection mode is exited (native RF
228	  // selection + our selectedNodes mirror). Skip the initial mount so this
229	  // doesn't run before the user has ever entered selection mode.
230	  const prevIsSelectionModeRef = useRef(false);
231	  useEffect(() => {
232	    if (prevIsSelectionModeRef.current && !selection.isSelectionMode) {
233	      setSelectedNodes([]);
234	      setNodes((ns) =>
235	        ns.map((n) => (n.selected ? { ...n, selected: false } : n)),
236	      );
237	    }
238	    prevIsSelectionModeRef.current = selection.isSelectionMode;
239	  }, [selection.isSelectionMode]);
240	
241	  const inSelectionMode = selection.isSelectionMode;
242	
243	  const relation = useRelationCreation();
244	
245	  const pending = usePendingMember({
246	    onHorizontalRelationReady: relation.startHorizontalRelation,
247	  });
248	  const memberSheetDeepLink = useMemo(readMemberSheetDeepLink, []);
249	  const consumedMemberSheetDeepLinkRef = useRef(false);
250	  const attemptedMemberSheetRestoreRef = useRef<string | null>(null);
251	
252	  useEffect(() => {
253	    const deepLinkState = consumedMemberSheetDeepLinkRef.current
254	      ? undefined
255	      : memberSheetDeepLink;
256	    const requestedState = deepLinkState ?? savedMemberSheetState;
257	    const treeId = activeTree?.id;
258	    if (publicView || !requestedState || !treeId || pending.editingMemberId) {
259	      return;
260	    }
261	
262	    const savedMember = members.find(
263	      (member) => member.id === requestedState.memberId,
264	    );
265	    if (savedMember) {
266	      attemptedMemberSheetRestoreRef.current = null;
267	      setOpenSheet(treeId, requestedState);
268	      if (deepLinkState) {
269	        consumedMemberSheetDeepLinkRef.current = true;
270	        clearMemberSheetDeepLink();
271	      }
272	      pending.setEditingMemberId(savedMember.id);
273	      pending.setIsEditMode(requestedState.mode === "edit");
274	    } else if (
275	      isReady &&
276	      windowed &&
277	      attemptedMemberSheetRestoreRef.current !== requestedState.memberId
278	    ) {
279	      attemptedMemberSheetRestoreRef.current = requestedState.memberId;
280	      void setFocusRoot(requestedState.memberId);
281	    } else if (isReady) {
282	      clearOpenSheet(treeId);
283	      if (deepLinkState) {
284	        consumedMemberSheetDeepLinkRef.current = true;
285	        clearMemberSheetDeepLink();
286	      }
287	    }
288	  }, [
289	    activeTree?.id,
290	    clearOpenSheet,
291	    isReady,
292	    memberSheetDeepLink,
293	    members,
294	    pending.editingMemberId,
295	    pending.setEditingMemberId,
296	    pending.setIsEditMode,
297	    publicView,
298	    savedMemberSheetState,
299	    setOpenSheet,
300	    setFocusRoot,
301	    windowed,
302	  ]);
303	
304	  // --- Unions, edges & visibility — computed off the main thread ---
305	  const { unions, baseEdges, hiddenNodeIds } = useDerivedFlowView(
306	    members,
307	    visibleRelationTypes,
308	    edgeType,
309	  );
310	
311	  // Resolve each union dot's colour the same way edges are styled: the
312	  // relation-type default merged with the admin override. Without this the
313	  // dot ignores configured colours (the edges are styled in the worker).
314	  const relationTypes = useTreeStore((s) => s.relationTypes);
315	  const resolveUnionColor = useMemo(() => {
316	    const byId = new Map(relationTypes.map((rt) => [rt.id, rt]));
317	    return (relationType?: string): string => {
318	      const rt = relationType ? byId.get(relationType) : undefined;
319	      return resolveRelationStyle(
320	        relationType ?? "",
321	        rt ? relationStyleOverrideFromType(rt) : undefined,
322	      ).stroke;
323	    };
324	  }, [relationTypes]);
325	
326	  // Use `nodes` (local state, updates on every drag frame) rather than `members`
327	  // (store, lags by the debounce) so union dots track their parents in real-time.
328	  // Carry the measured height: card height varies with content (e.g. source-tree
329	  // badges in virtual views), and the side handles sit at the measured mid-height.
330	  const nodePositions = useMemo(
331	    () =>
332	      new Map(
333	        nodes.map((n) => [
334	          n.id,
335	          {
336	            x: n.position.x,
337	            y: n.position.y,
338	            height: n.measured?.height ?? NODE_HEIGHT,
339	          },
340	        ]),
341	      ),
342	    [nodes],
343	  );
344	
345	  const unionNodes = useMemo<Node[]>(
346	    () =>
347	      unions
348	        .filter(
349	          (u) =>
350	            nodePositions.has(u.partner1Id) && nodePositions.has(u.partner2Id),
351	        )
352	        .map((u) => {
353	          const p1 = nodePositions.get(u.partner1Id)!;
354	          const p2 = nodePositions.get(u.partner2Id)!;
355	          const unionMemberPairHighlighted =
356	            connection.connectionPath.edgeKeys.has(
357	              memberPairKey(u.partner1Id, u.partner2Id),
358	            );
359	          const unionChildHighlighted = u.childIds.some((childId) =>
360	            [u.partner1Id, u.partner2Id].some((parentId) =>
361	              connection.connectionPath.edgeKeys.has(
362	                memberPairKey(parentId, childId),
363	              ),
364	            ),
365	          );
366	          const isUnionConnectionPath =
367	            connection.hasConnectionPath &&
368	            (unionMemberPairHighlighted || unionChildHighlighted);
369	
370	          return {
371	            id: u.id,
372	            type: "unionNode",
373	            // Hide the union dot when a partner is collapsed away, so it does
374	            // not linger with dangling connector edges.
375	            hidden:
376	              hiddenNodeIds.has(u.partner1Id) ||
377	              hiddenNodeIds.has(u.partner2Id),
378	            position: {
379	              x: (p1.x + p2.x) / 2 + NODE_WIDTH / 2 - UNION_NODE_SIZE / 2,
380	              // Center the dot at the average mid-height of the partner cards
381	              // (where their side handles sit) so the connector edges run level.
382	              y:
383	                (p1.y + p1.height / 2 + p2.y + p2.height / 2) / 2 -
384	                UNION_NODE_SIZE / 2,
385	            },
386	            data: {
387	              ...u,
388	              color: resolveUnionColor(u.relationType),
389	              isConnectionPath: isUnionConnectionPath,
390	              isConnectionDimmed:
391	                connection.isConnectionMode &&
392	                connection.hasConnectionPath &&
393	                !isUnionConnectionPath,
394	              onAddChildToUnion: pending.onAddChildToUnion,
395	              isReadOnly: isCanvasReadOnly,
396	            },
397	            draggable: false,
398	            selectable: false,
399	            focusable: false,
400	            // Pre-set dimensions so React Flow skips its ResizeObserver
401	            // measurement cycle and renders the node visible immediately.
402	            width: UNION_NODE_SIZE,
403	            height: UNION_NODE_SIZE,
404	            // Pre-declare handles so React Flow's isNodeInitialized()
405	            // returns true without waiting for DOM-based handle measurement.
406	            // Without this, getEdgePosition() returns null and edges are invisible.
407	            handles: [
408	              {
409	                id: "left",
410	                type: "target" as const,
411	                position: Position.Left,
412	                x: 0,
413	                y: 0,
414	                width: 1,
415	                height: UNION_NODE_SIZE,
416	              },
417	              {
418	                id: "right",
419	                type: "source" as const,
420	                position: Position.Right,
421	                x: 0,
422	                y: 0,
423	                width: UNION_NODE_SIZE,
424	                height: UNION_NODE_SIZE,
425	              },
426	              {
427	                id: "bottom",
428	                type: "source" as const,
429	                position: Position.Bottom,
430	                x: 0,
431	                y: 0,
432	                width: UNION_NODE_SIZE,
433	                height: UNION_NODE_SIZE,
434	              },
435	            ],
436	          };
437	        }),
438	    [
439	      unions,
440	      nodePositions,
441	      resolveUnionColor,
442	      connection.connectionPath.edgeKeys,
443	      connection.hasConnectionPath,
444	      connection.isConnectionMode,
445	      hiddenNodeIds,
446	      pending.onAddChildToUnion,
447	      isCanvasReadOnly,
448	    ],
449	  );
450	
451	  const openLinkedTree = useTreeStore((s) => s.openLinkedTree);
452	  const allTrees = useTreeStore((s) => s.trees);
453	  // Tree ids the user has listed access to (own + shared) — used to mute
454	  // linked-tree badges pointing at trees not shared with them. In the public
455	  // view there is no tree list, so accessibility is unknown (undefined).
456	  const accessibleTreeIds = useMemo(
457	    () =>
458	      publicView || allTrees.length === 0
459	        ? undefined
460	        : new Set(allTrees.map((tr) => tr.id)),
461	    [publicView, allTrees],
462	  );
463	  const handleOpenLinkedTree = useMemo(
464	    () =>
465	      treeLinksEnabled
466	        ? (treeId: string, memberId?: string | null) => {
467	            void openLinkedTree(treeId, memberId).catch(() => {
468	              toast.error(t("tree-view.linked-tree.open-error"));
469	            });
470	          }
471	        : undefined,
472	    [treeLinksEnabled, openLinkedTree, t],
473	  );
474	
475	  // Collapsed ancestors hide their descendant member nodes (handled in
476	  // useFlowNodes) and the union dots between them (above). Edges touching any
477	  // hidden member/union must also be hidden, otherwise React Flow keeps drawing
478	  // floating lines. Union ids are hidden when either partner is hidden.
479	  const hiddenElementIds = useMemo(() => {
480	    const ids = new Set<string>(hiddenNodeIds);
481	    for (const u of unions) {
482	      if (hiddenNodeIds.has(u.partner1Id) || hiddenNodeIds.has(u.partner2Id)) {
483	        ids.add(u.id);
484	      }
485	    }
486	    return ids;
487	  }, [hiddenNodeIds, unions]);
488	
489	  const viewNodes = useFlowNodes(
490	    nodes,
491	    pending.setEditingMemberId,
492	    pending.setIsEditMode,
493	    pending.onAddChild,
494	    pending.onAddParent,
495	    (id) => pending.onAddHorizontal(id, "left"),
496	    (id) => pending.onAddHorizontal(id, "right"),
497	    locator.highlightedNodeId,
498	    isCanvasReadOnly,
499	    connection.connectionSelectedIds,
500	    connection.connectionPath.nodeIds,
501	    connection.isConnectionMode,
502	    connection.hasConnectionPath,
503	    hiddenNodeIds,
504	    handleOpenLinkedTree,
505	    publicView,
506	    accessibleTreeIds,
507	    selection.isSelectionMode,
508	  );
509	  const viewEdges = useFlowEdges(
510	    baseEdges,
511	    connection.connectionPath.edgeKeys.size > 0
512	      ? connection.connectionPath.edgeKeys
513	      : EMPTY_EDGE_KEYS,
514	    hiddenElementIds,
515	  );
516	
517	  const {
518	    onNodesChange,
519	    onEdgesChange,
520	    onConnect,
521	    onSelectionChange,
522	    debouncedSave,
523	    pendingUpdates,
524	  } = useFlowInteractions(
525	    members,
526	    edges,
527	    unions,
528	    setNodes,
529	    setEdges,
530	    setMembersToDelete,
531	    setSelectedNodes,
532	    relation.setNewRelation,
533	  );
534	
535	  useEffect(() => {
536	    setEdges(viewEdges);
537	  }, [viewEdges]);
538	
539	  useEffect(() => {
540	    if (!isReady) return;
541	    initializeFlow();
542	  }, [members, isReady]);
543	
544	  // Re-center when the focus root changes in windowed mode.
545	  const prevFocusRootRef = useRef<string | null>(null);
546	  useEffect(() => {
547	    if (!windowed || !rfInstance) return;
548	    if (focusRootId === prevFocusRootRef.current) return;
549	    prevFocusRootRef.current = focusRootId;
550	    requestAnimationFrame(() => fitViewToAllNodes(rfInstance, 0.2));
551	  }, [windowed, focusRootId, rfInstance]);
552	
553	  // Virtual views: the viewport is a global setting (not per-tree), so after a
554	  // virtual view loads we must fit the view regardless of where the camera was.
555	  // The ref prevents re-fitting on every drag (nodes change) — once per view id.
556	  const fittedViewRef = useRef<string | null>(null);
557	  useEffect(() => {
558	    if (!isReady || !rfInstance || !isVirtualView || !activeTree) return;
559	    if (nodes.length === 0) return;
560	    if (fittedViewRef.current === activeTree.id) return;
561	    fittedViewRef.current = activeTree.id;
562	    requestAnimationFrame(() => fitViewToAllNodes(rfInstance, 0.2));
563	  }, [isReady, rfInstance, isVirtualView, activeTree, nodes]);
564	
565	  useEffect(() => {
566	    setSelectedNodes((prevSelected) => {
567	      const nodeMap = new Map(nodes.map((n) => [n.id, n]));
568	      return prevSelected
569	        .map((node) => nodeMap.get(node.id))
570	        .filter((n) => n !== undefined);
571	    });
572	  }, [nodes]);
573	
574	  const rearrangeNodes = () => {
575	    debouncedSave.cancel();
576	    pendingUpdates.current = {};
577	    updateLayout().then(() => {
578	      if (rfInstance) fitViewToAllNodes(rfInstance);
579	    });
580	  };
581	
582	  const handleAddFirstMember = () => {
583	    if (!rfInstance) return;
584	    const flowPoint = rfInstance.screenToFlowPosition({
585	      x: window.innerWidth / 2,
586	      y: window.innerHeight / 2,
587	    });
588	    pending.addFirstMember({
589	      x: flowPoint.x - NODE_WIDTH / 2,
590	      y: flowPoint.y,
591	    });
592	  };
593	
594	  const confirmDelete = () => {
595	    membersToDelete.forEach((member) => {
596	      void removeMember(member.id);
597	    });
598	    setNodes((currentNodes) =>
599	      currentNodes.filter(
600	        (node) => !membersToDelete.some((m) => m.id === node.id),
601	      ),
602	    );
603	    setMembersToDelete([]);
604	  };
605	
606	  if (!activeTree) {
607	    return availableTreeCount === 0 ? <NoDatabasePlaceholder /> : null;
608	  }
609	
610	  if (!isReady) return null;
611	
612	  return (
613	    <div className="w-full h-full" aria-label={t("tree-view.canvas-label")}>
614	      <ReactFlow
615	        className={`ft-tree-canvas${inSelectionMode ? " cursor-crosshair" : ""}`}
616	        nodes={[...viewNodes, ...unionNodes]}
617	        edges={edges}
618	        nodeTypes={nodeTypes}
619	        edgeTypes={edgeTypes}
620	        onlyRenderVisibleElements
621	        onNodesChange={
622	          (!canDragLayout && isCanvasReadOnly) || connection.isConnectionMode
623	            ? undefined
624	            : onNodesChange
625	        }
626	        onEdgesChange={
627	          isCanvasReadOnly || connection.isConnectionMode || inSelectionMode
628	            ? undefined
629	            : onEdgesChange
630	        }
631	        onConnect={
632	          isCanvasReadOnly || connection.isConnectionMode || inSelectionMode
633	            ? undefined
634	            : onConnect
635	        }
636	        defaultEdgeOptions={{ type: edgeType }}
637	        onSelectionChange={
638	          isCanvasReadOnly || connection.isConnectionMode
639	            ? undefined
640	            : onSelectionChange
641	        }
642	        onNodeClick={connection.handleNodeClick}
643	        minZoom={0.1}
644	        snapToGrid={true}
645	        snapGrid={[50, 50]}
646	        nodesDraggable={
647	          !connection.isConnectionMode && !isLockedScreen && canDragLayout
648	        }
649	        nodesConnectable={
650	          !connection.isConnectionMode &&
651	          !isLockedScreen &&
652	          !isCanvasReadOnly &&
653	          !inSelectionMode
654	        }
655	        elementsSelectable={
656	          connection.isConnectionMode || (!isLockedScreen && !isCanvasReadOnly)
657	        }
658	        nodesFocusable={true}
659	        autoPanOnNodeFocus={true}
660	        disableKeyboardA11y={false}
661	        edgesFocusable={!connection.isConnectionMode && !isCanvasReadOnly}
662	        deleteKeyCode={
663	          isCanvasReadOnly || connection.isConnectionMode
664	            ? null
665	            : ["Backspace", "Delete"]
666	        }
667	        connectOnClick={
668	          !connection.isConnectionMode && !isCanvasReadOnly && !inSelectionMode
669	        }
670	        connectionMode={ConnectionMode.Loose}
671	        connectionRadius={40}
672	        selectionOnDrag={inSelectionMode}
673	        panOnDrag={inSelectionMode ? [1, 2] : undefined}
674	        selectionMode={inSelectionMode ? SelectionMode.Partial : undefined}
675	        // In selection mode every click toggles a member (see
676	        // SelectionModeController); disabling the modifier key stops the
677	        // built-in handler from turning multi-selection back off.
678	        multiSelectionKeyCode={inSelectionMode ? null : undefined}
679	        // With multi-selection forced on, selecting on drag-start would toggle
680	        // (deselect) the node you grab to move; select on click instead so
681	        // dragging a selected member keeps the selection intact.
682	        selectNodesOnDrag={inSelectionMode ? false : undefined}
683	        onInit={setRfInstance}
684	        defaultViewport={viewport}
685	        onMoveEnd={(_, vp) => activeTree && setViewport(activeTree.id, vp)}
686	        ariaLabelConfig={{
687	          "controls.zoomIn.ariaLabel": t("tree-view.controls.zoom-in"),
688	          "controls.zoomOut.ariaLabel": t("tree-view.controls.zoom-out"),
689	          "controls.fitView.ariaLabel": t("tree-view.controls.fit-view"),
690	        }}
691	      >
692	        <SelectionModeController active={inSelectionMode} />
693	        <Background />
694	        <Panel position="top-right" className="pt-2 pr-2">
695	          <PresenceChips />
696	        </Panel>
697	        <GenerationLines
698	          visible={generationLineGap !== null}
699	          gap={generationLineGap ?? undefined}
700	        />
701	        {members.length === 0 && !isCanvasReadOnly && (
702	          <Panel
703	            position="top-center"
704	            className="!left-1/2 !-translate-x-1/2 !top-1/2 !-translate-y-1/2"
705	          >
706	            <EmptyTreeState onAddFirstMember={handleAddFirstMember} />
707	          </Panel>
708	        )}
709	        <Panel
710	          position={isMobile ? "top-center" : "top-left"}
711	          className={isMobile ? "w-[calc(100vw-1rem)] pt-2" : "pt-2"}
712	        >
713	          <div className="flex flex-col gap-1">
714	            <CanvasSearch
715	              members={members}
716	              onLocate={locator.locateMember}
717	              className={isMobile ? "w-full" : undefined}
718	              windowed={windowed}
719	              treeId={activeTree?.id}
720	              onFocusRoot={setFocusRoot}
721	              onOpenOtherTree={openTreeAndLocateMember}
722	            />
723	            {windowed && neighborhoodTruncated && (
724	              <div className="rounded-md border bg-background/90 px-3 py-1.5 text-xs text-muted-foreground shadow-md">
725	                {t("tree-view.windowed.banner", {
726	                  count: members.length,
727	                  total: totalMemberCount,
728	                })}
729	              </div>
730	            )}
731	          </div>
732	        </Panel>
733	        {connection.isConnectionMode &&
734	          connection.connectionRelations.length > 0 && (
735	            <Panel position="top-center" className="!top-2 pointer-events-none">
736	              {/* Cap the stack at ~3 cards; scroll the rest so many selected
737	                  members don't overflow the canvas. */}
738	              <div className="pointer-events-auto flex max-h-[15rem] flex-col gap-2 overflow-y-auto px-1 py-1">
739	                {connection.connectionRelations.map((rel) => (
740	                  <ConnectionRelationCard
741	                    key={`${rel.aId}|${rel.bId}`}
742	                    relation={rel}
743	                    onLocate={(id) => {
744	                      const target = members.find((m) => m.id === id);
745	                      if (target) locator.locateMember(target);
746	                    }}
747	                  />
748	                ))}
749	              </div>
750	            </Panel>
751	          )}
752	        {inSelectionMode && (
753	          <Panel position="top-center" className="!top-2">
754	            <div className="flex items-center gap-2 rounded-md border bg-background/90 px-3 py-1.5 text-xs shadow-md">
755	              <span>
756	                {t("tree-view.selection.selected-count", {
757	                  count: selectedNodes.length,
758	                })}
759	              </span>
760	              <span className="text-muted-foreground">
761	                {t("tree-view.selection.hint")}
762	              </span>
763	              <Button
764	                variant="ghost"
765	                size="sm"
766	                className="h-auto px-2 py-0.5 text-xs"
767	                onClick={() => {
768	                  setSelectedNodes([]);
769	                  setNodes((ns) =>
770	                    ns.map((n) => (n.selected ? { ...n, selected: false } : n)),
771	                  );
772	                }}
773	              >
774	                {t("tree-view.selection.clear")}
775	              </Button>
776	            </div>
777	          </Panel>
778	        )}
779	        <Panel position="bottom-left" className="pb-2 flex flex-col gap-2">
780	          <FlowPanelControls
781	            navigationOnly={isCanvasReadOnly}
782	            isConnectionMode={connection.isConnectionMode}
783	            connectionDisabled={members.length < 2}
784	            onToggleConnectionMode={connection.toggleConnectionMode}
785	            isSelectionMode={selection.isSelectionMode}
786	            onToggleSelectionMode={selection.toggleSelectionMode}
787	            selectionAvailable={!isCanvasReadOnly}
788	            selectionDisabled={members.length < 1 || isLockedScreen}
789	          />
790	        </Panel>
791	        {(!isCanvasReadOnly || isVirtualView) && (
792	          <Panel position="bottom-right" className="pb-2">
793	            <MemberControls
794	              nodes={nodes}
795	              selectedNodes={selectedNodes}
796	              setMembersToDelete={setMembersToDelete}
797	              onEditMember={(member) => pending.editExisting(member)}
798	              onCreateNewMember={(member) => pending.createNew(member)}
799	              onRearrange={rearrangeNodes}
800	              readOnly={isVirtualView}
801	            />
802	          </Panel>
803	        )}
804	      </ReactFlow>
805	      {/* The public read-only view is purely visual: no detail sheet or edit
806	          dialogs are mounted. */}
807	      {!publicView && (
808	        <>
809	          <RemoveMemberDialog
810	            isOpen={!!membersToDelete.length}
811	            members={membersToDelete}
812	            onConfirm={confirmDelete}
813	            onCancel={() => setMembersToDelete([])}
814	          />
815	          <MemberSheet
816	            isOpen={!!pending.editingMember}
817	            onClose={pending.closeSheet}
818	            member={pending.editingMember}
819	            initialEditMode={pending.isEditMode}
820	            canEdit={!isMobile && canWrite}
821	            isNewMember={pending.isNewMemberSession}
822	            onDiscardNewMember={pending.discardNewMember}
823	            onSaveNewMember={pending.saveNewMember}
824	          />
825	          <AddRelationDialog
826	            isOpen={relation.isDialogOpen}
827	            onClose={relation.closeDialog}
828	            onConfirm={relation.confirmRelation}
829	          />
830	        </>
831	      )}
832	    </div>
833	  );
834	
835	  function initializeFlow() {
836	    // Rebuilt on every `members` change (incl. drag-position persistence), so
837	    // carry the current selection over — otherwise moving a selected member
838	    // would clear the selection once its new position is saved.
839	    setNodes((prevNodes) => {
840	      const selectedIds = new Set(
841	        prevNodes.filter((n) => n.selected).map((n) => n.id),
842	      );
843	      return members.map((member) => ({
844	        id: member.id,
845	        type: "familyMember",
846	        position: member.position,
847	        data: member,
848	        selected: selectedIds.has(member.id),
849	      }));
850	    });
851	  }
852	};
853

