135	          </TooltipContent>
136	        </Tooltip>
137	        {tasksEnabled && (
138	          <Tooltip>
139	            <TooltipTrigger asChild>
140	              <Button
141	                variant={showTaskIndicators ? "default" : "secondary"}
142	                size="icon"
143	                onClick={() => setShowTaskIndicators(!showTaskIndicators)}
