270	
271	      {/* Collapse/Expand Controls */}
272	      <ButtonGroup orientation="vertical">
273	        <Tooltip>
274	          <TooltipTrigger asChild>
275	            <Button
276	              variant="secondary"
277	              size="icon"
278	              onClick={onCollapseMembers}
279	              disabled={selectedNoExpandedMember()}
280	              aria-label={t("collapse-children")}
281	            >
282	              <ChevronsDownUp />
283	            </Button>
284	          </TooltipTrigger>
285	          <TooltipContent side="left">{t("collapse-children")}</TooltipContent>
286	        </Tooltip>
287	        <Tooltip>
288	          <TooltipTrigger asChild>
289	            <Button
290	              variant="secondary"
291	              size="icon"
292	              onClick={onExpandMembers}
293	              disabled={selectedNoCollapsedMember()}
294	              aria-label={t("expand-children")}
295	            >
296	              <ChevronsUpDown />
297	            </Button>
298	          </TooltipTrigger>
299	          <TooltipContent side="left">{t("expand-children")}</TooltipContent>
300	        </Tooltip>
301	        <Tooltip>
302	          <TooltipTrigger asChild>
303	            <Button
304	              variant="secondary"
305	              size="icon"
306	              onClick={onExpandAllMembers}
307	              disabled={noCollapsedMember()}
308	              aria-label={t("expand-all-children")}
309	            >
310	              <ListChevronsUpDown />
311	            </Button>
312	          </TooltipTrigger>
313	          <TooltipContent side="left">
314	            {t("expand-all-children")}
315	          </TooltipContent>
316	        </Tooltip>
317	      </ButtonGroup>
318	
319	      {!readOnly && <Separator className="my-1" />}
320	
321	      {/* Member Add/Remove — hidden in read-only (virtual view) mode */}
322	      {!readOnly && (
323	        <ButtonGroup orientation="vertical">
324	          <Tooltip>
325	            <TooltipTrigger asChild>
326	              <Button
327	                variant="secondary"
328	                size="icon"
329	                onClick={onAddMember}
330	                disabled={isLockedScreen}
331	                aria-label={t("add-person")}
332	                className="text-green-600 hover:bg-green-50 hover:text-green-700"
333	                data-tutorial="add-member"
334	              >
335	                <UserPlus size={20} />
336	              </Button>
337	            </TooltipTrigger>
338	            <TooltipContent side="left">{t("add-person")}</TooltipContent>
339	          </Tooltip>
340	          <Tooltip>
341	            <TooltipTrigger asChild>
342	              <Button
343	                variant="secondary"
344	                size="icon"
345	                onClick={onRemoveMembers}
346	                disabled={!selectedNodes.length || isLockedScreen}
347	                aria-label={t("remove-person")}
348	                className="text-red-600 hover:bg-red-50 hover:text-red-700"
349	              >
350	                <UserMinus />
351	              </Button>
352	            </TooltipTrigger>
353	            <TooltipContent side="left">{t("remove-person")}</TooltipContent>
354	          </Tooltip>
355	        </ButtonGroup>
356	      )}
357	    </div>
358	  );
359	
360	  async function onAddMember() {
361	    const NODE_HEIGHT = 157;
362	    const BOTTOM_MARGIN = 50;
363	    const flowPoint = screenToFlowPosition({
364	      x: window.innerWidth / 2,
365	      y: window.innerHeight - BOTTOM_MARGIN - NODE_HEIGHT,
366	    });
367	
368	    const position = {
369	      x: flowPoint.x - NODE_WIDTH / 2,
370	      y: flowPoint.y,
371	    };
372	
373	    const newMember = createMember(position);
374	    onCreateNewMember(newMember);
375	  }
376	
377	  function onRemoveMembers() {
378	    setMembersToDelete(selectedNodes.map((node) => node.data as Member));
379	  }
380	
381	  function onExpandMembers() {
382	    batchSetCollapsed(
383	      selectedNodes.map((n) => ({ id: n.id, isCollapsed: false })),
384	    );
385	  }
386	
387	  function onExpandAllMembers() {
388	    batchSetCollapsed(nodes.map((n) => ({ id: n.id, isCollapsed: false })));
389	  }
390	
391	  function onCollapseMembers() {
392	    batchSetCollapsed(
393	      selectedNodes.map((n) => ({ id: n.id, isCollapsed: true })),
394	    );
395	  }
396	
397	  function selectedNoCollapsedMember() {
398	    return selectedNodes.every((node) => !node.data.isCollapsed);
399	  }
400	
401	  function selectedNoExpandedMember() {
402	    return selectedNodes.every((node) => node.data.isCollapsed);
403	  }
404	
405	  function noCollapsedMember() {
406	    return nodes.every((node) => !node.data.isCollapsed);
407	  }
408	};
409

